  methods: {
    handleVisibleChange(visible) {
      // 仅透传 visible-change 事件，下拉定位/宽度/层级全部交给 Element UI / Popper.js。
      // 历史实现（[0,32,80,160,320]ms 五个定时器 + 无条件 updatePopper + 手写
      // position:fixed/top/left/transform + getMaxLayerZIndex 全表 getComputedStyle）
      // 与 Popper.js 自身的定位互相覆盖、且每次又基于上一轮抬高自己的 z-index 造成
      // 反馈放大，展开下拉时即表现为「页面抖动」（禅道#6173）。
      // 经隔离复现实验确认：完全交由 Element UI 后宽度（= 选择框宽度）与层级
      // （弹窗内下拉 z-index 高于遮罩）均正确，且无任何重排/掉帧。
      this.$emit('visible-change', visible)
    }
  }
}

tool_input.old_string:
  methods: {
    handleVisibleChange(visible) {
      this.$emit('visible-change', visible)
      if (!visible) {
        this.cancelQueuedPopperStyle()
        return
      }
      // 下拉定位完全交给 Element UI / Popper.js（与 MultiSelect 一致）。
      // 旧实现用 [0,32,80,160,320]ms 五个定时器反复 syncPopperStyle，每次都
      // 无条件 select.updatePopper() 并手写 position:fixed/top/left/transform，
      // 与 Popper.js 自己的 transform 定位互相覆盖；再加上 getMaxLayerZIndex()
      // 每次全表 getComputedStyle 强制同步布局，展开下拉时即表现为「页面抖动」。
      // 这里只补一次宽度与层级，且值不变不写，从根上消除反复重排。
      this.queuePopperStyle()
    },
    cancelQueuedPopperStyle() {
      if (!this.popperFrameId) return
      cancelAnimationFrame(this.popperFrameId)
      this.popperFrameId = 0
    },
    queuePopperStyle() {
      this.cancelQueuedPopperStyle()
      this.popperFrameId = requestAnimationFrame(() => {
        this.popperFrameId = 0
        // 等一帧让 el-select 挂好 popper；拿不到就放弃，定位仍由原生 Popper.js 负责
        this.$nextTick(() => this.applyPopperStyle())
      })
    },
    getMaxLayerZIndex() {
      return Array.from(document.querySelectorAll('.v-modal, .el-dialog__wrapper, .el-select-dropdown, .el-popper'))
        .map((element) => Number(window.getComputedStyle(element).zIndex) || 0)
        .reduce((max, current) => Math.max(max, current), 0)
    },
    applyPopperStyle() {
      const select = /** @type {any} */ (this.$refs.elSelect)
      const popper = select?.popperElm
      if (!popper) return
      const selectWidth = Math.ceil(select.$el?.getBoundingClientRect?.().width || 0)
      if (selectWidth > 0) {
        const width = `${selectWidth}px`
        if (popper.style.width !== width) popper.style.width = width
        if (popper.style.minWidth !== width) popper.style.minWidth = width
      }
      const maxLayerZIndex = this.getMaxLayerZIndex()
      if (maxLayerZIndex > 0) {
        const nextZIndex = `${maxLayerZIndex + 10}`
        if (popper.style.zIndex !== nextZIndex) popper.style.zIndex = nextZIndex
      }
    }
  },
  beforeDestroy() {
    this.cancelQueuedPopperStyle()
  }
}

